struct block {
    void* ptr = nullptr;
    size_t length = 0;
    explicit operator bool() const { return ptr != nullptr; }
    void reset() { ptr = nullptr; length = 0; }
};

namespace alb {
namespace stack_allocator_impl {

inline size_t round_to_alignment(size_t alignment, size_t n) {
    return (n + alignment - 1) & ~(alignment - 1);
}

inline bool is_last_used_block(const char* data, const char* p, const block& b) {
    return (static_cast<char*>(b.ptr) + b.length == p);
}

inline void block_copy(const block& source, block& destination) noexcept {
    std::memcpy(destination.ptr, source.ptr, std::min(source.length, destination.length));
}

bool reallocate(char*& p, const char* data, size_t max_size, size_t alignment, block& b, size_t n) {
    if (b.length == n) {
        return true;
    }

    if (n == 0) {
        // Deallocate the block
        if (is_last_used_block(data, p, b)) {
            p = static_cast<char*>(b.ptr);
        }
        b.reset();
        return true;
    }

    if (!b) {
        // Allocate new block
        const auto alignedLength = round_to_alignment(alignment, n);
        if (alignedLength + p > data + max_size) {
            return false; // out of memory
        }
        b.ptr = p;
        b.length = alignedLength;
        p += alignedLength;
        return true;
    }

    const auto alignedLength = round_to_alignment(alignment, n);

    if (is_last_used_block(data, p, b)) {
        // Try in-place expansion/shrink
        if (static_cast<char*>(b.ptr) + alignedLength <= data + max_size) {
            b.length = alignedLength;
            p = static_cast<char*>(b.ptr) + alignedLength;
            return true;
        }
        // out of memory for expansion
        return false;
    }

    if (b.length > n) {
        // Shrink (not last block)
        b.length = alignedLength;
        return true;
    }

    // Expand but not last block - need to allocate new and copy
    block newBlock;
    const auto newAlignedLength = round_to_alignment(alignment, n);
    if (newAlignedLength + p > data + max_size) {
        return false; // out of memory
    }
    newBlock.ptr = p;
    newBlock.length = newAlignedLength;
    p += newAlignedLength;

    if (newBlock) {
        block_copy(b, newBlock);
        b = newBlock;
        return true;
    }
    return false;
}

